function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });
    const [moved, setMoved] = useState(false);

    const move = () => {
        const x = Math.random() * (window.innerWidth - 200);
        const y = Math.random() * (window.innerHeight - 100);

        setPos({ x, y });
        setMoved(true);
    };

    return (
        <div className="home-page">

            <h1 className="title">Will you be my Valentine? 💝</h1>

            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>

            <button
                className="brutalist-button button-1 no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={
                    moved
                        ? { left: pos.x, top: pos.y, position: "absolute" }
                        : { position: "relative" }
                }
            >
                NO 😜
            </button>

        </div>
    );
}



/* ================= GAME ================= */

function DinoGamePage() {

    const [started, setStarted] = useState(false);
    const iframeRef = useRef(null);
    const [key, setKey] = useState(0);


    const startGame = () => {
        setStarted(true);
        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };

    const retryGame = () => {
        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };


    return (
        <div className="game-page">

            <h2 style={{ color: "#ff6b9d" }}>Papa Run</h2>

            {!started && (
                <button
                    className="brutalist-button button-1 no-brutal"
                    onClick={startGame}
                >
                    ▶ Start Game
                </button>
            )}

            {started && (
                <>

                    <div className="game-frame">

                        <iframe
                            key={key}
                            ref={iframeRef}
                            src="/dino.html"
                            title="Papa Game"
                            tabIndex="0"
                        />

                    </div>


                    <div style={{ display: "flex", gap: "15px" }}>

                        <button
                            className="brutalist-button button-1 no-brutal"
                            onClick={retryGame}
                        >
                            🔄 Retry
                        </button>

                    </div>

                </>
            )}

            <p style={{ opacity: 0.7 }}>
                Press SPACE to Jump
            </p>

        </div>
    );
}



/* ================= INPUT ================= */

function InputPage({
                       userName,
                       setUserName,
                       selectedColor,
                       setSelectedColor,
                       onSubmit,
                   }) {

    const colors = ["Pink","Peach","Lavender","Mint","Coral","Blue"];

    return (
        <div className="input-page">

            <div className="input-card">

                <h2>Tell me about you 💕</h2>

                <input
                    className="text-input"
                    value={userName}
                    onChange={e => setUserName(e.target.value)}
                    placeholder="Your name"
                />

                <select
                    className="text-input"
                    value={selectedColor}
                    onChange={e => setSelectedColor(e.target.value)}
                >
                    <option value="">Choose color</option>

                    {colors.map(c => (
                        <option key={c}>{c}</option>
                    ))}
                </select>

                <button
                    className="submit-button"
                    disabled={!userName || !selectedColor}
                    onClick={onSubmit}
                >
                    Submit 💌
                </button>

            </div>

        </div>
    );
}



/* ================= FINAL ================= */

function FinalPage({ userName, selectedColor }) {

    return (
        <div className="final-page">

            <h1 className="final-message">
                Thank You {userName} 💖
            </h1>

            <p>You chose {selectedColor} 🌸</p>

            <div style={{ fontSize: "4rem" }}>🎁</div>

        </div>
    );
}
